/* { dg-do compile } */
/* { dg-options "-g" } */

struct {
  unsigned long len;
  unsigned long size;
  char data[];
};			/* { dg-warning "unnamed struct" } */
struct {
  struct {
    unsigned long len;
    unsigned long size;
    char data[6];
  };
};			/* { dg-warning "unnamed struct" } */

/* { dg-do run } */
/* { dg-require-effective-target lto } */
/* { dg-options "-flto -O2" } */

struct foo { int x; char a[]; };

void test_bar(void* b);

__attribute__((noinline))
int test_foo(struct foo* a, void* b)
{
        a->x = 1;
        test_bar(b);
        return a->x;
}

int main()
{
        struct foo y;

        if (2 != test_foo(&y, &y))
                __builtin_abort();

        return 0;
}

// TU2
struct foo { int x; char a[0]; };

void test_bar(void* b)
{
        struct foo *p = b;
        p->x = 2;
}
